def to_rows(d, model, cond):
    rows = []
    for country, topic_map in d.items():
        for topic, vals in topic_map.items():
            rows.append({
                "model": model,           # 'GPT' / 'LLaMA'
                "condition": cond,        # 'Role' / 'Native'
                "country": country,       # 'America', 'Iran', 'System' (assistant), ...
                "topic": int(topic),
                "measure": float(vals["measure"]),
            })
    return rows

def build_df():
    rows = []
    rows += to_rows(gpt_rolebased,   "GPT",   "Role")
    rows += to_rows(gpt_native,      "GPT",   "Native")
    rows += to_rows(llama_rolebased, "LLaMA", "Role")
    rows += to_rows(llama_native,    "LLaMA", "Native")
    return pd.DataFrame(rows)

def get_val(topic, country, model, cond):
    m = df[(df["topic"]==topic) & (df["country"]==country) &
           (df["model"]==model) & (df["condition"]==cond)]
    return m["measure"].iloc[0] if len(m) > 0 else np.nan

df = build_df()

series = [("GPT","Role"), ("GPT","Native"), ("LLaMA","Role"), ("LLaMA","Native")]
colors = {
    ("GPT","Role"):   "#4c78a8",
    ("GPT","Native"): "#72b7b2",
    ("LLaMA","Role"): "#f58518",
    ("LLaMA","Native"): "#e45756",
}

map_topics = [
    (3,  "We should fight for the abolition of nuclear weapons", "No nuclear weapons"),
    (4,  "We should legalize sex selection", "Legalize sex selection"),
    (15, "We should end the use of economic sanctions", "No economic sanctions"),
    (17, "We should legalize prostitution", "Legalize prostitution"),
    (18, "We should adopt a multi-party system", "Adopt multi-party system"),
    (22, "We should adopt atheism", "Adopt atheism"),
    (36, "We should introduce compulsory voting", "Compulsory voting"),
    (40, "We should adopt libertarianism", "Adopt libertarianism"),
]
topic_mappings = {tid: {"full": full, "short": short} for tid, full, short in map_topics}
topics_order = [tid for tid, _, _ in map_topics]

outdir = Path("results/agreement_ratio_plots/figs2")
outdir.mkdir(parents=True, exist_ok=True)

countries_all = sorted(set(df["country"]))
assistant_aliases = ["System", "Assistant", "without_role", "Neutral", "Baseline"]
assistant_found = next((c for c in countries_all if c in assistant_aliases), None)

countries = [c for c in countries_all if c != assistant_found]
country_labels = {c: ("Assistant" if c == assistant_found else c) for c in countries_all}

for topic in topics_order:
    values = np.array([
        [get_val(topic, country, m, c) for (m, c) in series]
        for country in countries
    ])

    if assistant_found is None:
        raise ValueError("Assistant not found among countries; can't draw reference lines.")
    assistant_vals = np.array([get_val(topic, assistant_found, m, c) for (m, c) in series])

    x = np.arange(len(countries))
    width = 0.18
    offsets = np.linspace(-1.5*width, 1.5*width, len(series))

    plt.figure(figsize=(8.8, 4.2))
    for (m, c), offset, col_idx in zip(series, offsets, range(len(series))):
        plt.bar(
            x + offset, values[:, col_idx],
            width=width, color=colors[(m, c)],
            label=f"{m} ({c})", edgecolor="black", linewidth=0.5
        )
        # Assistant reference line for this series
        plt.axhline(
            assistant_vals[col_idx], linestyle="--", linewidth=1,
            alpha=0.9, color=colors[(m, c)]
        )

    plt.xticks(x, [country_labels.get(cc, cc) for cc in countries], rotation=45, ha="right")
    plt.ylim(0, 1)
    plt.ylabel("Agreement ratio")
    plt.title(topic_mappings[topic]["full"])
    plt.grid(axis="y", linestyle="--", alpha=0.3)
    plt.legend(ncol=2, frameon=False)
    plt.tight_layout()
    plt.savefig(outdir / f"agreement_topic_{topic}_with_assistant_reference.png", dpi=300)
    plt.savefig(outdir / f"agreement_topic_{topic}_with_assistant_reference.pdf")
    plt.close()
